rollback.sql:
DROP FUNCTION IF EXISTS nexus.hybrid_search_384(vector, text, text[], jsonb, int);
DROP FUNCTION IF EXISTS nexus.hybrid_search_768(vector, text, text[], jsonb, int);
DROP FUNCTION IF EXISTS nexus.hybrid_search_1024(vector, text, text[], jsonb, int);
